CREATE TABLE IF NOT EXISTS telemetry_landing.smpp_provider_ops_v1 (
 tenant_id String,project_id String,environment LowCardinality(String),mapping_version UInt32,policy_version UInt32,source_system LowCardinality(String),source_product String,source_record_id UUID,source_record_hash FixedString(64),source_schema_name LowCardinality(String),source_schema_version LowCardinality(String),record_type LowCardinality(String),priority LowCardinality(String),runtime_instance_id String,deployment_id String,collector_id String,provider_id String,provider_instance_id String,task_id Nullable(String),resource_id Nullable(String),operation_name Nullable(String),correlation_id Nullable(String),causation_record_id Nullable(String),trace_id Nullable(String),span_id Nullable(String),occurred_at DateTime64(3,'UTC'),emitted_at DateTime64(3,'UTC'),received_at DateTime64(3,'UTC'),ingested_at DateTime64(3,'UTC'),attributes_json String,payload_json String,envelope_json String,wal_segment UInt64,wal_offset UInt64,ingest_version UInt64
) ENGINE=ReplacingMergeTree(ingest_version) PARTITION BY toYYYYMM(occurred_at) ORDER BY (tenant_id,project_id,source_system,source_record_id,source_record_hash) TTL toDateTime(occurred_at) + INTERVAL 180 DAY DELETE;
CREATE TABLE IF NOT EXISTS telemetry_landing.smpp_provider_ops_conflict_v1 (tenant_id String,project_id String,environment LowCardinality(String),mapping_version UInt32,source_record_id UUID,accepted_record_hash FixedString(64),conflicting_record_hash FixedString(64),provider_id String,record_type LowCardinality(String),occurred_at DateTime64(3,'UTC'),received_at DateTime64(3,'UTC'),conflict_summary String,wal_segment UInt64,wal_offset UInt64) ENGINE=ReplacingMergeTree(received_at) PARTITION BY toYYYYMM(received_at) ORDER BY (tenant_id,project_id,source_record_id,accepted_record_hash,conflicting_record_hash,wal_segment,wal_offset) TTL toDateTime(received_at) + INTERVAL 365 DAY DELETE;
CREATE TABLE IF NOT EXISTS telemetry_landing.smpp_provider_ops_rejected_summary_v1 (rejection_id UUID,collector_id String,source_hint String,error_code String,error_summary String,received_at DateTime64(3,'UTC')) ENGINE=MergeTree PARTITION BY toYYYYMM(received_at) ORDER BY (error_code,received_at,rejection_id) TTL toDateTime(received_at) + INTERVAL 90 DAY DELETE;
CREATE VIEW IF NOT EXISTS telemetry_landing.provider_ops_raw_v1 AS SELECT tenant_id,project_id,environment,mapping_version,source_record_id AS record_id,source_record_hash AS record_hash,record_type,source_schema_name AS schema_name,source_schema_version AS schema_version,provider_id,runtime_instance_id AS instance_id,task_id,resource_id,operation_name,correlation_id,occurred_at,emitted_at,received_at,ingested_at,attributes_json,payload_json,envelope_json,wal_segment,wal_offset,ingest_version FROM telemetry_landing.smpp_provider_ops_v1;
